head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > contextMenuAltClick]<br/>contextMenu=true 일때 Body 영역에서 Alt + 마우스 좌클릭으로 컨텍스트 메뉴를 표시할지 설정합니다.",
    "validation" : [
        "true 설정 시 Body 영역에서 Alt + 마우스 좌클릭 시 우클릭과 동일하게 WebSquare 컨텍스트 메뉴를 표시합니다.",
        "Header 영역은 적용되지 않으며 Body 영역에 데이터가 로드된 영역만 적용됩니다.",
        "미설정 또는 false 설정 시 Body 영역에서 Alt + 마우스 좌클릭 시 WebSquare 컨텍스트 메뉴를 표시하지 않습니다. (기본값 false)",
        "false 설정 시 일반 마우스 좌클릭과 동일하게 처리되며, 포커스 이동, EditMode 진입, oncellclick 이벤트등의 동작이 Cell 클릭과 동일하게 수행됩니다.",
        "contextMenuAltClick 속성은 Body 의 데이터 로드 영역에서 Alt + 마우스 좌클릭을 우클릭으로 대체하는 처리를 수행하며 WebSquare 컨텍스트의 표시 여부는 contextMenu 속성에 의해 결정됩니다.",
        "contextMenu=false 이면 Body 의 데이터 영역에서 Alt + 마우스 좌클릭 시 onrightbuttonclick 이벤트만 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    //  - Alt + 좌클릭 은 사용자 액션으로 수행되므로 안내 라벨로 조작 방법을 표시
    $c.gcm.createLabel('label="■ Body 데이터 영역의 Cell 을 Alt + 마우스 좌클릭 하여 동작을 확인하세요. (Header 는 미적용)"', '', 'label1');

    // 조건 설정
    //  - con_contextMenuAltClick / con_contextMenu 가 미설정('') 이면
    //    createCList 가 빈 문자열 value 를 자동 제외하므로 properties 키 자체가 빠짐 (기본값 동작)
    //  - contextMenuAltClick 효과(Alt+좌클릭으로 메뉴 표시)는 contextMenu=true 일 때만 메뉴가 뜸 (전제)
    let properties = {
        dataList: "data:dlt_bind",
        contextMenuAltClick: con_contextMenuAltClick.getValue(),
        contextMenu: con_contextMenu.getValue(),
    };

    let cList = $c.gcm.createCList(properties);

    // oncontextopen / onrightbuttonclick / oncellclick 이벤트 핸들러 부착
    let eList = $c.gcm.createEList(["oncontextopen", "onrightbuttonclick", "oncellclick"]);

    // dataList 생성 (기본 데이터 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// oncontextopen : 컨텍스트 메뉴가 표시될 때 발생
//  - contextMenuAltClick=true + contextMenu=true 환경에서 Alt+좌클릭 시 우클릭과 동일하게 메뉴 표시
//  - 컨텍스트 메뉴는 oncontextopen 이후 생성되므로 setTimeout 으로 생성 후 DOM 검증
scwin.target1_oncontextopen = function (rowIndex, columnIndex, focusedCellInfo, info) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextopen rowIndex : " + rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextopen columnIndex : " + columnIndex);

    setTimeout(function () {
        let menu = document.querySelector("[id$='_contextMenu_list']");
        if (!menu) {
            wf_body_bottom.getObj("scwin").setReturnValue("컨텍스트 메뉴 미생성");
            return;
        }
        wf_body_bottom.getObj("scwin").setReturnValue("'w2grid_contextMenu' 클래스 설정 여부 : " + menu.classList.contains("w2grid_contextMenu"));
    }, 0);
};



// onrightbuttonclick : Body 영역에서 우클릭(또는 contextMenuAltClick=true 시 Alt+좌클릭) 시 발생
//  - contextMenu=false 이면 Alt+좌클릭 시 메뉴는 미표시되고 onrightbuttonclick 만 발생
scwin.target1_onrightbuttonclick = function (rowIndex, columnIndex, e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onrightbuttonclick rowIndex : " + rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("onrightbuttonclick columnIndex : " + columnIndex);
};



// oncellclick : false(기본) 환경에서 Alt+좌클릭이 일반 좌클릭처럼 처리되어 Cell 클릭과 동일하게 발생
scwin.target1_oncellclick = function (rowIndex, columnIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncellclick rowIndex : " + rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("oncellclick columnIndex : " + columnIndex);
};
